public class BidService {
  private final BidDAO bidDAO;
  private final AuctionDAO auctionDAO;
  private final TransactionManager transactionManager;
  private final BidValidator bidValidator;
  private final AntiSnipeService antiSnipeService;

  // Updated constructor to receive dependencies via injection for testability
  public BidService(BidDAO bidDAO, AuctionDAO auctionDAO, TransactionManager transactionManager,
                    BidValidator bidValidator, AntiSnipeService antiSnipeService) {
    this.bidDAO = bidDAO;
    this.auctionDAO = auctionDAO;
    this.transactionManager = transactionManager;
    this.bidValidator = bidValidator;
    this.antiSnipeService = antiSnipeService;
  }

  public PlaceBidResponse placeBid(int sessionId, int userId, long bidAmount) {
    BidResult result =
        transactionManager.runInTransaction(
            conn -> {
              auctionDAO.lockRow(conn, sessionId);
              Auction auction =
                  auctionDAO
                      .findById(conn, sessionId)
                      .orElseThrow(() -> new RuntimeException("Phiên đấu giá không tồn tại."));
              bidValidator.validateAuctionState(auction);
              bidValidator.validateBidAmount(bidAmount, auction.getHighestBid());
              bidValidator.validateSelfBid(userId, auction.getWinnerId());
              auction.updateHighestBid(bidAmount, userId);
              antiSnipeService.apply(auction);
              bidDAO.insertBid(conn, sessionId, userId, bidAmount, false);
              auctionDAO.update(conn, auction);
              return new BidResult(auction.getId(), auction.getHighestBid(), auction.getWinnerId());
            });
    return new PlaceBidResponse(
        true, result.sessionId(), result.highestBid(), result.winnerId(), "Success");
  }

  public PlaceBidResponse placeBidAndBuildResponse(int sessionId, int userId, long bidAmount) {
    // Reuse existing placeBid logic and return the response directly
    return placeBid(sessionId, userId, bidAmount);
  }
}

package app.network;

import app.enums.PacketType;
import app.exception.AppException;
import app.exception.ConnectException;
import app.models.Packet;
import app.models.User;
import app.utils.JsonUtil;
import java.io.*;
import java.net.Socket;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Client {
  private static volatile Client instance;
  private Socket socket;
  private User currentUser;
  private BufferedWriter writer;
  private BufferedReader reader;
  Map<PacketType, List<Consumer<Response>>> observersMap = new HashMap<>();
  private boolean connected = false;
  Logger logger = LoggerFactory.getLogger(Client.class);

  private Client() {}

  public static Client getInstance() {
    if (instance == null) {
      synchronized (Client.class) {
        if (instance == null) instance = new Client();
      }
    }
    return instance;
  }

  public void connect() throws IOException {
    logger.info("[CLIENT] Đang kết nối...");
    socket = new Socket("127.0.0.1", 5000);
    logger.info("[CLIENT] Kết nối thành công!");
    writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream()));
    writer.flush();
    reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
    Thread thread = new Thread(this::listen);
    thread.setDaemon(true);
    thread.start();
    connected = true;
  }

  private void listen() {
    try {
      String line;
      while ((line = reader.readLine()) != null) {
        try {
          Packet packet = JsonUtil.fromJson(line, Packet.class);
          Response response = JsonUtil.decodeResponse(packet);
          if (response != null) {
            notify(packet.getType(), response);
          } else {
            logger.warn("[CLIENT] No response mapping for type: {}", packet.getType());
          }
        } catch (AppException e) {
          logger.info(e.getMessage());
        }
      }
    } catch (IOException e) {
      connected = false;
      throw new ConnectException("Mất kết nối" + e.getMessage());
    } finally {
      closeResources();
    }
  }

  public boolean connected() {
    return connected;
  }

  public void sendRequest(Packet packet) throws IOException {
    if (writer != null) {
      String json = JsonUtil.toJson(packet);
      writer.write(json);
      writer.newLine();
      writer.flush();
    }
  }

  public void notify(PacketType packetType, Response response) {
    List<Consumer<Response>> users = observersMap.get(packetType);
    if (users != null) {
      for (Consumer<Response> listener : users) {

        listener.accept(response);
      }
    }
  }

  //  public void setOnMessageReceived(Consumer<Packet> observer) {
  //    for (PacketType packetType : PacketType.values()) {
  //      subscribe(packetType, observer);
  //    }
  //  }

  public void subscribe(PacketType packetType, Consumer<Response> observer) {
    observersMap.computeIfAbsent(packetType, k -> new ArrayList<>()).add(observer);
  }

  public <T extends Response> void subscribe(
      PacketType packetType, Class<T> responseType, Consumer<T> observer) {
    subscribe(
        packetType,
        response -> {
          if (responseType.isInstance(response)) {
            observer.accept(responseType.cast(response));
          } else {
            logger.warn(
                "[CLIENT] Unexpected response type for {}: {}",
                packetType,
                response == null ? "null" : response.getClass().getName());
          }
        });
  }

  public void unsubscribe(PacketType packetType, Consumer<Response> observer) {
    List<Consumer<Response>> users = observersMap.get(packetType);
    if (users != null) {
      users.remove(observer);
    }
  }

  public User getCurrentUser() {
    return currentUser;
  }

  public void setCurrentUser(User currentUser) {
    this.currentUser = currentUser;
  }

  public void closeResources() {
    try {
      logger.info("[CLIENT] Closing resources");
      connected = false;
      if (reader != null) reader.close();
      if (writer != null) writer.close();
      if (socket != null) socket.close();
    } catch (IOException e) {
      logger.warn("Lỗi khi đóng kết nối: {}", e.getMessage());
    }
  }
}

